def remove_empty_and_sort(strings: list[str]) -> list[str]:
    """从字符串列表中移除空字符串，并按长度从长到短排序。"""
    non_empty = [s for s in strings if s]
    return sorted(non_empty, key=len, reverse=True)

words = ["banana", "", "kiwi", "", "blueberry", "fig"]
print(remove_empty_and_sort(words))

