def filter_and_sort(strings: list[str]) -> list[str]:
    """Remove empty strings and sort by length in descending order."""
    filtered = [s for s in strings if s]
    return sorted(filtered, key=len, reverse=True)

example = ["banana", "", "kiwi", "apple", "", "fig", "grape"]
